//
// card.scss
//

.card {
    box-shadow: $box-shadow-sm;
    margin-bottom: $grid-gutter-width;
    background-color: #ffffffc2 !important;
    .card-drop {
        color: #{map-get($grays, '600')};
        font-size: 20px;
        display: inline-block;
        line-height: 1px;
    }
}

